CategoryTheory.NatTrans.ext  ∀ {C : Type u₁} {inst : CategoryTheory.Category.{v₁, u₁} C} {D : Type u₂} {inst_1 : CategoryTheory.Category.{v₂, u₂} D}
  {F G : CategoryTheory.Functor C D} {x y : CategoryTheory.NatTrans F G}, x.app = y.app → x = y  -- Extensionality Lemma for Natural Transformations
CategoryTheory.Functor.HomObj.ext_iff  ∀ {C : Type u} {inst : CategoryTheory.Category.{v, u} C} {D : Type u'} {inst_1 : CategoryTheory.Category.{v', u'} D}
  {F G : CategoryTheory.Functor C D} {A : CategoryTheory.Functor C (Type w)} {x y : F.HomObj G A}, x = y ↔ x.app = y.app  -- Extensionality of Natural Transformations
CategoryTheory.CatCenter.ext_iff  ∀ {C : Type u} [inst : CategoryTheory.Category.{v, u} C] {x y : CategoryTheory.CatCenter C},
  x = y ↔ ∀ (X : C), x.app X = y.app X  -- Extensionality of the Center of a Category
CategoryTheory.SingleFunctors.Hom.ext_iff  ∀ {C : Type u_1} {D : Type u_2} {inst : CategoryTheory.Category.{v_1, u_1} C}
  {inst_1 : CategoryTheory.Category.{v_2, u_2} D} {A : Type u_5} {inst_2 : AddMonoid A}
  {inst_3 : CategoryTheory.HasShift D A} {F G : CategoryTheory.SingleFunctors C D A} {x y : F.Hom G},
  x = y ↔ x.hom = y.hom  -- Extensionality of Natural Transformations Between SingleFunctors
CategoryTheory.BasedNatTrans.ext  (β : BasedNatTrans F G) (h : α.toNatTrans = β.toNatTrans) : α = β  -- Extensionality for Based Natural Transformations

